  'sentio.policy.obsolete.tag': { pt: 'OBSOLETE · Aguardando atualização', en: 'OBSOLETE · Awaiting update' },
  'sentio.obsolete.notice': {
    pt: '<span><strong>Status do Projeto — OBSOLETE (Aguardando melhoria e atualização):</strong> O aplicativo Sentio encontra-se temporariamente descontinuado para novos recursos enquanto passa por reestruturação técnica e melhorias. Esta Política de Privacidade permanece <strong>integralmente ativa e válida</strong> para todos os usuários que possuem versões anteriores instaladas e para fins de conformidade junto à Google Play.</span>',
    en: '<span><strong>Project Status — OBSOLETE (Awaiting improvements &amp; update):</strong> The Sentio application is temporarily paused for new releases while undergoing technical restructuring and improvements. This Privacy Policy remains <strong>fully active and valid</strong> for all users with existing installations and for Google Play compliance.</span>'
  },

  'sentio.toc.1': { pt: '1. Informações que coletamos',        en: '1. Information We Collect' },
  'sentio.toc.2': { pt: '2. Como usamos suas informações',     en: '2. How We Use Your Information' },
