  'guardalinha.policy.subtitle': { pt: 'Proteção de Chamadas & Segurança', en: 'Call Protection & Security' },
  'guardalinha.policy.obsolete.tag': { pt: 'OBSOLETE · Aguardando atualização', en: 'OBSOLETE · Awaiting update' },
  'guardalinha.obsolete.notice': {
    pt: '<span><strong>Status do Projeto — OBSOLETE (Aguardando melhoria e atualização):</strong> O aplicativo GuardaLinha encontra-se temporariamente em fase de revisão e modernização técnica antes de receber novas versões. Esta Política de Privacidade permanece <strong>integralmente ativa e válida</strong> para todos os usuários com versões anteriores instaladas e para fins de conformidade junto à Google Play.</span>',
    en: '<span><strong>Project Status — OBSOLETE (Awaiting improvements &amp; update):</strong> The GuardaLinha application is temporarily paused for technical modernization and improvements before receiving new releases. This Privacy Policy remains <strong>fully active and valid</strong> for all users with existing installations and for Google Play compliance.</span>'
  },

  'guardalinha.toc.1': { pt: '1. Informações que coletamos',       en: '1. Information We Collect' },
  'guardalinha.toc.2': { pt: '2. Como usamos suas informações',    en: '2. How We Use Your Information' },
  'guardalinha.toc.3': { pt: '3. Permissões necessárias',          en: '3. Required Permissions' },
