  /* ════════════════════════════════════════════════════
     POLICY — BOOP (com.furrycore.boop · v1.0.0)
  ════════════════════════════════════════════════════ */
  'boop.policy.subtitle': { pt: 'Rede Social 4-em-1 · Retenção Zero Biométrica & ECA Digital', en: '4-in-1 Social Network · Biometric Zero-Retention & Child Safety' },
  'boop.policy.updated':  { pt: 'Última atualização: 23 de novembro de 2026', en: 'Last updated: November 23, 2026' },

  'boop.toc.1': { pt: '1. Dados da conta e publicações', en: '1. Account Data & Posts' },
