  'hive.discontinued.notice': {
    pt: '<span><strong>Aviso Oficial — PROJETO DESCONTINUADO (Sem versão estável prevista):</strong> O aplicativo experimental <strong>Hive (Hive Chat)</strong> teve seu desenvolvimento encerrado em definitivo pela Mancia Studios e <strong>não terá uma versão estável, publicação oficial na loja, atualizações futuras nem servidores relay ativos</strong>. Esta página permanece publicada exclusivamente para transparência histórica e conformidade com a LGPD. Toda a pesquisa de comunicação P2P criptografada evoluiu do zero para o nosso novo aplicativo <strong><a href="../nyxmesh/">NyxMesh</a></strong>.</span>',
    en: '<span><strong>Official Notice — PROJECT DISCONTINUED (No stable release planned):</strong> The experimental <strong>Hive (Hive Chat)</strong> application has permanently ended its development lifecycle at Mancia Studios and <strong>will not receive a stable version, official store release, future updates, or active relay servers</strong>. This page remains online strictly for historical transparency and LGPD compliance. Our encrypted P2P communication research was rebuilt from the ground up as <strong><a href="../nyxmesh/">NyxMesh</a></strong>.</span>'
  },
